/**
 * Unit tests for DeserializationConfig#initialize
 */
public class DeserializationConfig_initialize_TriageGen2Test {

    private BaseSettings baseSettings;
    private SubtypeResolver subtypeResolver;
    private SimpleMixInResolver mixins;
    private RootNameLookup rootNames;
    private DeserializationConfig config;
    private JsonParser mockParser;

    @Before
    public void setUp() {
        baseSettings = mock(BaseSettings.class);
        subtypeResolver = mock(SubtypeResolver.class);
        mixins = mock(SimpleMixInResolver.class);
        rootNames = mock(RootNameLookup.class);
        mockParser = mock(JsonParser.class);

        // Initialize the config using the public constructor
        config = new DeserializationConfig(baseSettings, subtypeResolver, mixins, rootNames);
    }

    @Test
    public void testInitialize_NoFeaturesToChange() {
        // When _parserFeaturesToChange == 0 and _formatReadFeaturesToChange == 0
        // We use a fresh config where no 'with' or 'without' methods have been called to modify features

        config.initialize(mockParser);

        verify(mockParser, never()).overrideStdFeatures(anyInt(), anyInt());
        verify(mockParser, never()).overrideFormatFeatures(anyInt(), anyInt());
    }

    @Test
    public void testInitialize_OnlyParserFeaturesToChange() {
        // Set parser features to change
        // We use 'with' to trigger the internal state change for _parserFeaturesToChange
        config = config.with(JsonParser.Feature.AUTO_CLOSE_SOURCE);

        // Since the fields are private, we rely on the 'with' methods to set the internal state
        // that makes _parserFeaturesToChange != 0
        config.initialize(mockParser);

        // Verify overrideStdFeatures was called
        // Note: The exact bitmask depends on Jackson internals, but we verify the call occurred
        verify(mockParser, times(1)).overrideStdFeatures(anyInt(), anyInt());
        // Verify format features was NOT called
        verify(mockParser, never()).overrideFormatFeatures(anyInt(), anyInt());
    }

    @Test
    public void testInitialize_OnlyFormatFeaturesToChange() {
        // Set format features to change
        config = config.with(FormatFeature.ALLOW_NON_NUMERIC_NUMBERS);

        config.initialize(mockParser);

        // Verify overrideStdFeatures was NOT called
        verify(mockParser, never()).overrideStdFeatures(anyInt(), anyInt());
        // Verify overrideFormatFeatures was called
        verify(mockParser, times(1)).overrideFormatFeatures(anyInt(), anyInt());
    }

    @Test
    public void testInitialize_BothFeaturesToChange() {
        // Set both types of features
        config = config.with(JsonParser.Feature.AUTO_CLOSE_SOURCE)
                       .with(FormatFeature.ALLOW_NON_NUMERIC_NUMBERS);

        config.initialize(mockParser);

        // Verify both methods were called
        verify(mockParser, times(1)).overrideStdFeatures(anyInt(), anyInt());
        verify(mockParser, times(1)).overrideFormatFeatures(anyInt(), anyInt());
    }
}
